import { test, expect } from '@playwright/test';

test.describe('Session Expired Message on Token Timeout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display session expired message when token times out', async ({ page }) => {
    // Intercept the API call and simulate token expiration
    await page.route('**/api/user/profile', (route) => {
      route.abort('timedout');
    });

    // Wait for the token to expire and the API call to fail
    await page.waitForTimeout(1000);

    // Verify the session expired message is visible
    const expiredMessage = page.getByText('Your session has expired');
    await expect(expiredMessage).toBeVisible();

    // Verify the user is redirected to the login page
    const loginLink = page.getByRole('link', { name: /login/i });
    await expect(loginLink).toBeVisible();
    await expect(page).toHaveURL(/.*login/);

    // Verify the logout button is visible and functional
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();
    await logoutButton.click();

    // Verify user is logged out and redirected to login
    await expect(page).toHaveURL(/.*login/);
  });

  test('should handle multiple failed token requests gracefully and show error state', async ({ page }) => {
    // Intercept multiple API calls and simulate token expiration
    await page.route('**/api/user/profile', (route) => {
      route.abort('timedout');
    });

    // Simulate a second failed request
    await page.route('**/api/user/settings', (route) => {
      route.abort('timedout');
    });

    // Wait for both requests to fail
    await page.waitForTimeout(2500);

    // Verify the session expired message is displayed
    const expiredMessage = page.getByText('Your session has expired');
    await expect(expiredMessage).toBeVisible();

    // Verify the user is not stuck in a loading state
    const loadingSpinner = page.locator('[data-testid="loading-spinner"]');
    await expect(loadingSpinner).not.toBeVisible();

    // Verify the user is redirected to the login page
    await expect(page).toHaveURL(/.*login/);

    // Verify the error message persists after redirect
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Session expired');

    // Verify the user can navigate back to dashboard (should redirect again)
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await dashboardLink.click();

    // Verify user is still on login page
    await expect(page).toHaveURL(/.*login/);
  });
});
